def sayfa(p):
    rows = S._surya_satirlari([types.SimpleNamespace(text=t, bbox=b) for t, b in SAYFA[p]], 72 / 200, None)
    no, rows = S._sayfa_no_ve_kenar(rows, 842)
    govde = sorted(r["h"] for r in rows)[len(rows) // 2]
    ana, dip = S._dipnot_ayir(rows, 842, govde)
    return no, ana, dip


